const format = function productMessage({ body }) {
  const escape = (text) => text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  for (const field of ['name', 'regular_price', 'sale_price', 'permalink', 'date_created']) if (typeof body[field] !== 'string') throw new Error('WooCommerce product is missing ' + field);
  const link = new URL(body.permalink);
  if (!['http:', 'https:'].includes(link.protocol) || link.username || link.password) throw new Error('Product permalink must be an HTTP(S) URL without credentials');
  const footer = 'Added: ' + escape(body.date_created);
  if (footer.length > 300) throw new Error('Product timestamp exceeds Slack footer size');
  const text = ':new: A new product has been added! :new:';
  return { text, attachments: [{ color: '#66FF00', fallback: text, fields: [
    { title: 'Name', value: escape(body.name), short: false },
    { title: 'Price', value: escape(body.regular_price), short: true },
    { title: 'Sale Price', value: escape(body.sale_price), short: true },
    { title: 'Link', value: escape(body.permalink), short: false },
  ], footer }] };
}

return {json:format({body:$json})};
